using System.Diagnostics;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;
namespace TsRecommend;
static class Program {
 static readonly string Home=Zoo.RuntimeConfiguration.Home;
 static string Rock=>Zoo.RuntimeConfiguration.Current.TvRockFolder;
 static readonly JsonSerializerOptions Json=new(){WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.CamelCase};
 static HttpClient Client=null!;static Uri Base=>Zoo.RuntimeConfiguration.BaseUri;
 static void Write(string path,object value){Directory.CreateDirectory(Path.GetDirectoryName(path)!);var temp=path+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(value,Json),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}
 static string StatusPath=>Path.Combine(Home,"recommend-status.json");
 static void Status(string state,string message,object? detail=null)=>Write(StatusPath,new{state,message,time=DateTimeOffset.Now,detail});
 static async Task<string> Get(string relative){var uri=new Uri(Base,relative);if(!Zoo.RuntimeConfiguration.IsAllowed(uri))throw new Exception("ローカルTVRock以外への接続を拒否しました。");bool mutation=uri.AbsolutePath.EndsWith("/regsch")||Data.Query(uri.PathAndQuery).ContainsKey("r");for(int attempt=0;;attempt++){try{using var response=await Client.GetAsync(uri);response.EnsureSuccessStatusCode();return Encoding.GetEncoding(932).GetString(await response.Content.ReadAsByteArrayAsync()).TrimEnd('\0');}catch(Exception ex) when(!mutation&&attempt<3&&(ex is HttpRequestException||ex is TaskCanceledException)){await Task.Delay(1500*(attempt+1));}}}
 static List<Booking> Current()=>Data.Bookings(Path.Combine(Rock,"tvrock.sch"));
 static async Task<Booking?> Confirm(Show p,HashSet<string> before){for(int i=0;i<8;i++){var matches=Current().Where(b=>!before.Contains(b.Id)&&b.Enabled&&Planner.SameBroadcast(p,b)&&Data.Norm(b.Title)==Data.Norm(p.Title)).ToList();if(matches.Count==1)return matches[0];await Task.Delay(500);}return null;}
 static async Task<int> Main(string[] args){Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);Directory.CreateDirectory(Home);if(args.Contains("--audit")){Console.WriteLine(JsonSerializer.Serialize(Current(),Json));return 0;}using var mutex=new Mutex(true,"Local\\TVRockZoo.Recommendations",out bool own);if(!own)return 0;if(args.Contains("--test")){try{Tests.Run();Console.WriteLine("PASS: recommendation tests");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}Client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(12)};var statePath=Path.Combine(Home,"recommend-state.json");var state=File.Exists(statePath)?JsonSerializer.Deserialize<State>(File.ReadAllText(statePath),Json)??new():new();string? snapshot=args.Contains("--snapshot")?args[Array.IndexOf(args,"--snapshot")+1]:null;bool apply=args.Contains("--apply");if(snapshot!=null&&apply)throw new Exception("保存済み番組表から実予約はできません。");bool scheduled=args.Contains("--scheduled");if(scheduled&&(File.Exists(Path.Combine(Home,"recommend-disabled.txt"))||state.NextDue>DateTimeOffset.Now))return 0;Client.DefaultRequestHeaders.ConnectionClose=true;string run=Path.Combine(Home,"recommend-history",DateTimeOffset.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(run);
 try{Status("running",apply?"おすすめの選定・予約を実行しています。":"予約を変更せず、おすすめ案を作成しています。");var now=DateTimeOffset.Now;var bookings=Current();var knownPath=Path.Combine(Home,"ai-recommendations.json");var known=File.Exists(knownPath)?JsonSerializer.Deserialize<List<Recommendation>>(File.ReadAllText(knownPath),Json)??[]:new List<Recommendation>();var aiIds=known.Select(r=>r.ReservationId).ToHashSet();bookings=bookings.Select(b=>aiIds.Contains(b.Id)?b with{Manual=false}:b).ToList();File.Copy(Path.Combine(Rock,"tvrock.sch"),Path.Combine(run,"tvrock-before.sch"),true);File.Copy(Path.Combine(Rock,"dtv.ini"),Path.Combine(run,"dtv-before.ini"),true);var (tuners,stations)=Data.Tuners(Path.Combine(Rock,"dtv.ini"));if(tuners.Count==0)throw new Exception("使用可能なチューナーが見つかりません。");string keywords=snapshot!=null?File.ReadAllText(Path.Combine(snapshot,"keywords.html")):await Get("kwl");File.WriteAllText(Path.Combine(run,"keywords.html"),keywords);var tastes=Data.Preferences(keywords,bookings.Where(b=>!aiIds.Contains(b.Id)).ToList());var consulted=ConsultPreferences.Load(Home);tastes=consulted.AddTo(tastes);if(tastes.Count==0)throw new Exception("好みの判断に使える検索条件・予約履歴がありません。");var shows=new List<Show>();var day=new DateTimeOffset(now.AddHours(-4).Date,now.Offset);for(int offset=0;offset<192;offset+=6){string html=snapshot!=null?File.ReadAllText(Path.Combine(snapshot,$"guide-{offset}.html")):await Get($"day?t={offset}&j=-1&k=-1&v=0");File.WriteAllText(Path.Combine(run,$"guide-{offset}.html"),html);shows.AddRange(Data.Guide(html,offset,day,stations));if(snapshot==null)await Task.Delay(150);}shows=shows.Where(show=>!known.Any(r=>r.Start>DateTimeOffset.Now&&!bookings.Any(b=>b.Id==r.ReservationId)&&r.Station==show.Station&&Math.Abs((r.Start-show.Start).TotalSeconds)<90)).ToList();shows=shows.GroupBy(s=>s.Key).Select(g=>g.OrderByDescending(s=>s.End).First()).ToList();if(shows.Count<20)throw new Exception("番組表を十分取得できませんでした。予約は変更しません。");bool newCycle=state.CycleStarted==null||now-state.CycleStarted>=TimeSpan.FromDays(3);if(newCycle){state.CycleStarted=now;state.AddedInCycle=0;state.Attempted.Clear();}int cap=Math.Max(0,20-state.AddedInCycle);var plan=Planner.Make(shows.Where(consulted.Allows).ToList(),bookings,tastes,tuners,now,cap);Write(Path.Combine(run,"plan.json"),plan);Write(Path.Combine(Home,"recommend-plan.json"),plan);if(!apply){Status("preview",$"おすすめ候補 {plan.Add.Count} 件、確実な重複 {plan.Remove.Count} 件。予約は未変更です。",new{run,plan.Programs,plan.Preferences});Console.WriteLine(JsonSerializer.Serialize(plan,Json));return 0;}
 var metadataPath=Path.Combine(Home,"ai-recommendations.json");var metadata=File.Exists(metadataPath)?JsonSerializer.Deserialize<List<Recommendation>>(File.ReadAllText(metadataPath),Json)??[]:[];var added=new List<string>();var removed=new List<string>();Write(statePath,state);
 foreach(var pick in plan.Add){var fresh=Current();if(state.Attempted.Contains(pick.Show.Key)||fresh.Any(b=>b.Enabled&&(Planner.SameBroadcast(pick.Show,b)||Planner.SameEpisode(pick.Show.Title,pick.Show.Description,b.Title,b.Fields.GetValueOrDefault("SUBTITLE","")))))continue;var device=Planner.FreeDevice(pick.Show,tuners,fresh,[]);if(device==null)continue;var q=Data.Query(pick.Show.Actions[device.Value]);if(q.GetValueOrDefault("r")!="1"||q.GetValueOrDefault("c")!=pick.Show.ServiceId.ToString()||q.GetValueOrDefault("e")!=pick.Show.EventId.ToString()||q.GetValueOrDefault("d")!=device.Value.ToString())throw new Exception("番組表の予約リンクの内容が一致しません。");state.Attempted.Add(pick.Show.Key);state.AddedInCycle++;Write(statePath,state);Write(Path.Combine(run,"attempt-"+state.AddedInCycle+".json"),new{pick,beforeIds=fresh.Select(b=>b.Id)});await Get(pick.Show.Actions[device.Value]);var created=await Confirm(pick.Show,fresh.Select(b=>b.Id).ToHashSet());if(created==null)throw new Exception("予約追加の結果を確認できません。二重登録を避けて処理を停止しました。");metadata.Add(new Recommendation(created.Id,created.Title,pick.SearchWord,pick.Reason,created.Start,created.Station));Write(metadataPath,metadata);added.Add(created.Id);Write(Path.Combine(run,"result.json"),new{added,removed});}
 foreach(var removal in plan.Remove){var fresh=Current();var target=fresh.SingleOrDefault(b=>b.Id==removal.Booking.Id);var keep=fresh.SingleOrDefault(b=>b.Id==removal.KeepId&&b.Enabled);if(target==null||keep==null||(target.Manual&&!metadata.Any(r=>r.ReservationId==target.Id))||target.Repeating||target.Start<DateTimeOffset.Now.AddMinutes(15)||!Planner.SameEpisode(target.Title,target.Fields.GetValueOrDefault("SUBTITLE",""),keep.Title,keep.Fields.GetValueOrDefault("SUBTITLE","")))continue;string html=await Get("reg?i="+target.Id);File.WriteAllText(Path.Combine(run,"deleted-"+target.Id+".html"),html);var fields=Data.Form(html,"予約を変更");fields.Remove("valid");if(fields.GetValueOrDefault("i")!=target.Id||Data.Norm(fields.GetValueOrDefault("title",""))!=Data.Norm(target.Title)||!fields.GetValueOrDefault("submit","").Contains("予約を変更"))throw new Exception("削除フォームの照合に失敗しました。");string deleteResponse=await Get("regsch?"+string.Join("&",fields.Select(p=>Data.Encode(p.Key)+"="+Data.Encode(p.Value))));File.WriteAllText(Path.Combine(run,"delete-response-"+target.Id+".html"),deleteResponse);await Task.Delay(500);if(Current().Any(b=>b.Id==target.Id&&b.Enabled))throw new Exception("重複無効化の結果を確認できません。処理を停止しました。");string suppressionPath=Path.Combine(Home,"duplicate-suppressions.json");var suppressions=File.Exists(suppressionPath)?JsonSerializer.Deserialize<List<Suppression>>(File.ReadAllText(suppressionPath),Json)??[]:[];suppressions.RemoveAll(x=>x.ReservationId==target.Id);suppressions.Add(new(target.Id,target.Title,keep.Id,removal.Reason));Write(suppressionPath,suppressions);removed.Add(target.Id);Write(Path.Combine(run,"result.json"),new{added,removed});}
 state.NextDue=now.AddDays(3);Write(statePath,state);Status("complete",$"おすすめ {added.Count} 件を追加、同じ回の重複 {removed.Count} 件を整理しました。",new{added,removed,nextDue=state.NextDue,run});return 0;
 }catch(Exception e){Status("failed",e.Message,new{run});File.WriteAllText(Path.Combine(run,"error.txt"),e.ToString());Console.Error.WriteLine(e);return 1;}finally{Client.Dispose();}}
}
record Suppression(string ReservationId,string ProgramTitle,string KeepId,string Reason);
record Recommendation(string ReservationId,string ProgramTitle,string SearchWord,string Reason,DateTimeOffset Start,string Station);
static class Tests {
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void Run(){string fixture=Path.GetTempFileName();File.WriteAllText(fixture,"0 START 2000000000\n0 END 2000000600\n0 UNIQID 10\n0 VALIDATE 1\n1 START 2000000700\n1 END 2000001300\n1 UNIQID 11\n1 VALIDATE 1\n",Data.Cp932);Assert(Data.Bookings(fixture).Count==2,"複数の予約連番を読み取れない");var now=DateTimeOffset.Now;Show S(int index,DateTimeOffset? start=null)=>new($"show-{index}",1,index,"NHK",$"工場見学「部品{index}の秘密」","金属部品を製造する職人の工夫を紹介します。",start??now.AddHours(2+index), (start??now.AddHours(2+index)).AddMinutes(30),new(){{5,"day?r=1&c=1&e="+index+"&d=5"}});Booking B(string id,DateTimeOffset start,int device=5)=>new(id,"既存予約","NHK",1,99,start,start.AddHours(1),device,true,true,false,[]);var tuners=new List<Tuner>{new(5,["NHK"])};Assert(Planner.FreeDevice(S(1,now.AddHours(2)),tuners,[B("a",now.AddHours(2))],[])==null,"競合を検出できない");Assert(Planner.FreeDevice(S(1,now.AddHours(4)),tuners,[B("a",now.AddHours(2))],[])==5,"空き枠を選べない");Assert(!Planner.SameEpisode("NHKスペシャル","番組説明","NHKスペシャル","番組説明"),"同名別回を誤判定");Assert(Planner.SameEpisode("工場見学「部品の秘密」[再]","","工場見学「部品の秘密」[字]",""),"再放送の同回を認識できない");Assert(!Planner.SameEpisode("工場見学「部品の秘密」","","工場見学「金属の秘密」",""),"別回を誤判定");var guide=Enumerable.Range(1,40).Select(i=>S(i)).ToList();var capTastes=guide.Select(p=>new Taste(p.Title,1)).ToList();var plan=Planner.Make(guide,[],capTastes,tuners,now);Assert(plan.Add.Count==20,"20件上限・選定失敗");var form=Data.Form("<form name='regsch'><input name='i' value='12' type='hidden'><input type='checkbox' name='valid' value='true' checked><input type='checkbox' name='watchonly' value='true'><input type='submit' name='submit' value='　予約を削除　'></form>","予約を削除");Assert(form["i"]=="12"&&form.ContainsKey("valid")&&!form.ContainsKey("watchonly")&&form["submit"].Contains("削除"),"フォーム保持失敗");Assert(Data.Encode("NHK 日本").Contains("%93%FA%96%7B"),"CP932符号化失敗");var r=new Ranker([new("MUSIC not (BRAND|BLOOD)",1),new("NHKスペシャル",1),new("サカナクション",1)]);Assert(r.Score(S(100) with{Title="BRAND NEW MUSIC"}).Score==0,"検索除外語を無視した");Assert(r.Score(S(101) with{Title="NHKスペシャルPR [字]"}).Score==0,"PR番組を除外できない");Assert(r.Score(S(102) with{Title="ハクション大魔王"}).Score==0,"無関係な語尾一致を推薦した");Assert(!Planner.SameEpisode("ニュース","毎日の全国のニュースや天気の情報を詳しくお届けします。","ニュース","毎日の全国のニュースや天気の情報を詳しくお届けします。"),"一般的な説明の一致だけで別回を消した");Assert(!Planner.SameEpisode("【ハートネットTV】","","【ハートネットTV】",""),"番組枠名だけで別回を消した");Assert(Planner.Make(guide,[],capTastes,tuners,now,3).Add.Count==3,"周期の残件数を超えた");Console.WriteLine("PASS: tuner conflict, free slot, same-episode vs generic title, 20-cap, form checkboxes, CP932 encoding.");}
}














